// HashSet — O(n)
const nums = __ll.array('nums', __input.nums);
const seen = __ll.set('seen');

for (let i = 0; i < nums.length; i++) {
  __ll.setVar('i', i);
  const num = nums[i];
  __ll.setVar('current', num);
  if (seen.has(num)) {
    __ll.note(`Duplicate found: ${num}`);
    return true;
  }
  seen.add(num);
}
__ll.note('No duplicates found');
return false;

// Brute Force C++ — O(n^2)
#include <iostream>
#include <vector>

using namespace std;

int main() {
  for (int i = 0; i < nums.size(); i++) {
    for (int j = i + 1; j < nums.size(); j++) {
      if (nums[i] == nums[j]) {
        cout << "Duplicate found: " << nums[i] << endl;
        return 0;
      }
    }
  }
  cout << "No duplicates found" << endl;
  return 0;
}
